const { env } = await import('node:process');
const raw = env['STROC_DOC'];
if (!raw) throw new Error('Missing STROC_DOC env var');
try { globalThis.doc = JSON.parse(raw); } catch (e) { throw new Error('Invalid JSON in STROC_DOC'); }

const { toPdf } = await import('@stroc/pdf');
const bytes = await toPdf(globalThis.doc, { pageSize: 'A4' });
if (!bytes) throw new Error('toPdf returned no data');
const { Buffer } = await import('node:buffer');
globalThis.pdfBase64 = Buffer.from(bytes).toString('base64');
